// ---- Events ----

/** Events sent by the Go side. Subscribe with `events.name.on(listener)`. */
export const events = {
  /**
   * AgentUpdated fires when a session changes in a way the UI must replace wholesale (status,
   * requests, queue, review, errors). Carries the full session.
   */
  agentsUpdated: event<Session>("agents:updated"),
  /**
   * AgentDelta fires for the frequent display-only changes of a live session (activity, tail,
   * last message, usage, diff counts); merge it into the held session.
   */
  agentsDelta: event<SessionDelta>("agents:delta"),
  /** AgentEvent carries one new entry of a session's history (message, tool use, permission request...). */
  agentsEvent: event<Event>("agents:event"),
  /** AgentRemoved fires when a session is deleted. */
  agentsRemoved: event<AgentRef>("agents:removed"),
  /** AgentRunUpdated fires when an orchestration run (loop-until, try-N) changes. */
  agentsRun: event<Run>("agents:run"),
  applicationsChanged: event<ApplicationRef>("applications:changed"),
  desktopNavigate: event<DesktopNavigation>("desktop:navigate"),
  /** SettingsWindowSection asks an already-open settings window to show a section. */
  settingsWindowSection: event<string>("settings-window:section"),
  /** TerminalOutput carries pty output; Data is base64. */
  terminalOutput: event<TerminalChunk>("terminal:output"),
  /** TerminalChanged fires when a terminal starts or exits. */
  terminalChanged: event<Info>("terminal:changed"),
  /** TerminalRemoved fires when a terminal is closed. */
  terminalRemoved: event<TerminalRef>("terminal:removed"),
  /** SettingChanged fires when a setting changes. */
  settingsChanged: event<SettingChange>("settings:changed"),
  /** DaemonState reports connection state of the daemon link. */
  daemonState: event<DaemonLink>("daemon:state"),
  chatMessage: event<Message>("chat:message"),
  /** ChatMessageDelta carries text appended to a streaming message between full chat:message snapshots. */
  chatMessageDelta: event<MessageDelta>("chat:message-delta"),
  /**
   * ChatCallMessage and ChatCallDelta carry the spoken turns of a phone call (Message.CallID set) for the call
   * pane; the chat timeline never receives them.
   */
  chatCallMessage: event<Message>("chat:call-message"),
  chatCallDelta: event<MessageDelta>("chat:call-delta"),
  chatRun: event<RunState>("chat:run"),
  chatBot: event<BotChange>("chat:bot"),
  chatMemory: event<MemoryChange>("chat:memory"),
  llmChanged: event<Change>("llm:changed"),
  /** DictationChanged carries the voice status after every change in the daemon (downloads report progress). */
  dictationChanged: event<VoiceStatus>("dictation:changed"),
  /** GitHubChanged fires when the GitHub connection or cached data changed. */
  githubChanged: event<GitHubChange>("github:changed"),
  /** GitHubClone reports progress of a clone started with GitHub.Clone. */
  githubClone: event<GitHubCloneEvent>("github:clone"),
  jarvisChanged: event<StatusView>("jarvis:changed"),
  mcpStatus: event<ServerState>("mcp:status"),
  mcpAuthUrl: event<AuthStart>("mcp:auth-url"),
  mcpAuthDone: event<AuthDone>("mcp:auth-done"),
  policyPending: event<ApprovalQueue>("policy:pending"),
  notificationsChanged: event<NotificationEvent>("notifications:changed"),
  filesChanged: event<FilesChanged>("files:changed"),
  filesRootsChanged: event<FileRootsChange>("files:rootsChanged"),
  pluginsChanged: event<PluginChange>("plugins:changed"),
  /** ProjectsChanged fires when the project registry changes. */
  projectsChanged: event<ProjectRef>("projects:changed"),
  /** WorktreesChanged fires when worktrees of a project were created or removed. */
  worktreesChanged: event<ProjectRef>("worktrees:changed"),
  /** SandboxStatus fires when a bot's computer changes state or the user takes over or hands back. */
  sandboxStatus: event<SandboxStatus>("sandbox:status"),
  /** SandboxScreen carries live screen bytes for an open screen; the last chunk of a stream has Closed set. */
  sandboxScreen: event<ScreenChunk>("sandbox:screen"),
  /** SandboxAvailability fires when whether bot computers can run here may have changed (setup or download ended). */
  sandboxAvailability: event<Availability>("sandbox:availability"),
  /** SandboxRuntime reports the runtime download's progress and result. */
  sandboxRuntime: event<RuntimeState>("sandbox:runtime"),
  /** SandboxSetup reports the Windows Hypervisor Platform setup: running, then its result. */
  sandboxSetup: event<SetupState>("sandbox:setup"),
  /**
   * SandboxActivity fires when a bot starts or finishes something on its computer (a command, a file write or a
   * browser action); the same id is sent again when it finishes.
   */
  sandboxActivity: event<ActivityEntry>("sandbox:activity"),
  /** SandboxHandoff fires when a bot starts or stops waiting for the user to take over its computer. */
  sandboxHandoff: event<HandoffState>("sandbox:handoff"),
} as const;
